import{_ as t,c as a,o as e,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"周易通论卷一","description":"周易通论 - 周易通论卷一","frontmatter":{"title":"周易通论卷一","description":"周易通论 - 周易通论卷一"},"headers":[],"relativePath":"zh/classics/tonglun/002.md","filePath":"zh/classics/tonglun/002.md"}'),n={name:"zh/classics/tonglun/002.md"};function r(o,p,c,_,i,l){return e(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="周易通论卷一" tabindex="-1">周易通论卷一 <a class="header-anchor" href="#周易通论卷一" aria-label="Permalink to “周易通论卷一”">​</a></h1><p>钦定四库全书</p><p>大学士李光地撰</p><p>易之兴也最古，其源流不可悉知。「三易」之名，及画卦、重卦、名卦之人，诸儒之论亦复不一。约之，则「三易」之说可通者有二：一曰夏连山、殷归藏、周周易也；一曰连山炎帝、归藏黄帝、周易文王也。画卦、重卦、名卦之人，则有三说：一曰伏羲画八卦，因自重之而自名之也；一曰伏羲画八卦，至文王乃重而名之也；一曰伏羲画八卦而重之，文王始名之也。今按，以「三易」为夏、殷、周者，据记有「夏时坤乾」之文也。谓为炎帝、黄帝、文王者，连山炎帝之号；归藏黄帝之号，而周文王之国号也。郑康成断从后说，今始沿之可也。周礼云：「三易之经卦皆八，其别皆六十有四」，则非文王始重卦可知。然伏羲虽已重卦，名则未备，盖其时仅有八卦之名而已。故系辞传曰：「其称名也，杂而不越，于稽其类，其衰世之意耶？」言卦之称名，错杂事物，周于人用，以其类考之，非中古以后更历世变者不能及也。况「履虎尾」、「否之匪人」、「同人于野」、「艮其背」、「中孚豚鱼」之类，皆辞与名连为义，则是一手所系，非仍旧名而增加之也。朱子于乾卦下本义云：三奇之卦，名之曰乾。是以八卦之名为伏羲所命。至屯卦下则无说，而于系传称名，则以为卦名也。是以六十四卦之名为文王所命也。于理近是，今亦从之。彖辞、爻辞，何人所系？夫子未尝分别。先儒直以箕子明夷、王享岐山之类，事出文王之后，断爻辞为周公所作。然考夫子赞易，如所谓「易之序也，爻之辞也，是故谓之象」，「是故谓之爻」，每以爻与象对，而反不及彖，似爻之起亦非在彖后者。意者系爻固文王之意，而周公成之与？惟曰：「彖者言乎象者也，爻者，言乎变者也。彖者材也，爻者效天下之动者也。智者观其彖辞，则思过半矣。」分别卦爻辞先后，其理甚明，先儒之说可循用也。夫子赞易曰：十翼者，彖上传、彖下传、象上传、象下传、乾坤文言、系辞上传、系辞下传、说卦、序卦、杂卦也。所谓象传者，兼二体，大象及六爻之小象也。按汉书本为经二卷，传十卷，经传离异，不相附属。自费直始以彖、象传缀于每卦经后，如乾、坤之例。王弼又自坤卦以下，以彖传、大象传附彖，小象传附爻，则今现行之易是也。朱子及东莱吕氏复古经传之旧，本义之作，实据汉书，故凡「彖曰」、「象曰」、「文言曰」之类为王弼所加者，悉已删去，而别有卷首标题，即彖传、「象传」、文言传等目。其彖传题下则注云：「彖即文王所系之辞；传者，夫子释经之辞也。」象传题下则注云：「象者，卦之上下两象及两象之六爻，周公所系之辞也。」十二卷古易于是乎各得其所矣。明初律令兼用程朱传义，及永乐中修大全书，离析本义，以从程传之序，故后虽本义孤行，而其序遂不复。学者读乾卦彖象传标题下注，茫然不省所指，故有以大象为周公作者，误由兹起也。为宜别刻本义原本，以悟初学。本义卷首诸图，朱子所作也。秦汉以来，伏羲画卦根本次第无言及者。邵康节先天之学源出希夷，程子不信，而朱子始表章之，此诸图所由作也。然惟八卦方位圆图及六十四卦圆图、方图为邵氏之旧，其首之以横图，则朱子用邵子之意而摹画以示人者，见于答袁机仲诸书可见也。间尝论易之源流，四圣之后，四贤之功为不可掩。盖自周子标太极之指，邵子定两仪以下之次，而伏羲之意明，程子归之于性命道德之要，其学以尚辞为先，而文周之理得，朱子收而兼用之，又特揭卜筮以存易之本教，分别象占以尽易之变通，于是乎由孔圣以追羲、文，而易之道粲然备矣。自汉以还，非无传者，然扬雄以玄为宗，则纯乎老氏矣。其与周子太极，可若是班乎？其法以三三起，虽与易卦相近，而非自然之理。八十一首之序，犹仍卦气之谬也。其与邵氏先天之法，亦未可同日语。王弼生于魏、晋，祖尚玄虚，即复之一卦，而宗指与程传迥别。盖王氏所谓复者，虚静之室；程传所谓复者，仁义之心。其余义准是矣。然当朱子时，太极抑于陆子兄弟，先天毁于袁枢、林栗，程学訾者亦众。苟非朱子一一极辩，则三家之学且熄，而卜筮象占之说，又所以佐三家之未逮也。自时厥后，好议论者犹将反之，故黄震攻康节之图，王祎申河洛之辩，罗钦顺灭太极之书，至于以卜筮为朱子诟厉者，又纷然而未已。夫学欲博而不欲杂，众言淆乱则折诸圣。易之为书，立说者最多，其杂且乱甚矣。夫苟不折以列圣群贤，而惟博之好，则易之贼也。航于断港绝潢，而望至于海，不亦难乎？</p><p>三代学校之教，诗、书、礼、乐四术而已。易掌于太卜，国史掌于史官，乃专官之学，未尝施于学校也。故韩宣子至鲁，乃见易象、春秋，则知诗、书、礼、乐列国有传，而二书者独𮤲。自夫子赞修之后，稍见于世矣。故记礼者名为六经，而庄周之徒颇知其意者，亦往往并述焉。然自秦政燔经，独存卜筮、医药、种树之书，而易幸不毁，则知其时犹未直目之经，学士先生犹未流行诵习，以故卜筮家专司而世守之，是则易之本教然也。汉人虽称六艺，然田何、施、孟、梁丘之学皆不传，不知其说云何。焦赣、京房衍为生克休咎之占，其敝以星日气候推配，虽曰流荡，然可知卜筮之教，展转相沿，久则难变也。扬雄作玄疑易，虽袭京、焦之绪，而颇推道德性命之指。至王弼始纯以理言易，而后之谈经者宗焉。是书著述莫盛于宋，惟邵康节之学有传，而犹以象数见讥。其余儒者所得，有浅有深，然大要承辅嗣之意，皆以易为言理之书而已。夫孔子尝言易矣，曰：「和顺于道德而理于义，穷理尽性以至于命。」则谓易言理是也。然本画卦系辞之初，则主于卜筮以明民，非如他书直阐其理，直述其事者也。朱子深探其本，作本义一编，专归卜筮，然而至今以为訾謷，盖恐狭易之用，小易之道，而使经为伎术者流也。殊不知易之用，以卜筮而益周，易之道，以卜筮而益妙。而凡经之象数辞义，皆以卜筮观之而后可通，初非小技末术之比也。今曰作易者，言理以教人尔，则施于学士，而阻于愚氓，其用不周矣。偏言一理，而不足以该于无穷，其道不妙矣。卦象之泛取，蓍数之旁通，其于理也，杂而不切矣。大有元亨，初六无咎，其于理也，略而难明矣。避其为小技末术，而反入于枝离晦昧之归，乃不虞其重为易病也乎？是故朱子之大有功于易卜筮之说也，有得于此，然后可以言洁静精微之要，而凡散殊清通，无所推而不达，道德性命亦无所求而不得矣。</p><p>朱子既复经、传次序，今不遵之，而从王弼旧本，何也？曰：「朱子之复古经、传也，虑四圣之书之混而为一也；今之仍旧本也，虑四圣之意之离而为二也。」盖后世之注经也，文义训诂而已，而又未必其得，故善读经者，且涵泳乎经文，使之浃洽，然后参以注解，未失也。若四圣之书，先后如一人之所为，互发相备，必合之而后识化工之神，则未可以离异观也。故以文、周彖、爻言之，彖于坤言牝马，可谓尽坤之情矣。乾未有象也，六爻则于乾言龙，以尽乾之道。坤彖言君子牝马之贞，有东北、西南，以应地之方也。乾爻则言圣人之龙德，有潜见飞跃，以应天之时。此则彖爻之自相补备者也。以夫子之传言之，乾彖曰「元亨利贞」，未有四时之义也，彖传释之，而曰「资始流形」，曰「各正保合」，则知四德之即四时矣。坤彖曰西南东北，未有四德之义也，文言释之，于西南曰「含物化光」，于东北曰「顺天时行」，则知四方之即四德矣。乾爻之总辞曰「见群龙无首」，著乾之居首而不为首也。象传则于坤曰「以大终」，著坤之居终而不为终焉。坤爻之总辞曰「用六永贞」，明用六之义，所重在贞也。象传则于乾曰「乾元用九」，明用九之义，所重在元也。此又经传之相为补备者，所谓先后如一人之所为也。若乃屯蒙以下诸卦，则皆有不可相离者。盖如彖言「建侯」，爻亦曰「建侯」，则知「侯」之为初矣；彖言「童蒙」，爻亦言「童蒙」，则知「童」之为五矣。此彖爻之互相发明者也。然如讼之彖曰「利见大人」，爻曰「讼元吉」，其意方明也，彖传曰「尚中正」，则知「大人」之为五矣。师之彖曰「丈人吉」，爻曰「在师中」，其意未明也，彖传曰「刚中而应」，则知「丈人」之为二矣。又如晋之「康侯」，而九四不足以当之，则未知其所指也，彖传曰「柔进而上行」，则知卦之「康侯」，不在四而在五矣。困之「大人」，亦未知其所指也，彖传曰「以刚中也」，则知卦之「大人」，不在阴而在阳矣。盖上以释文王名辞之意，而下以得周公系辞之心，故彖传为卦爻之枢要。至于大象，则卦之命名所取为多，故夫子特表而出之。凡</p><p>彖传释名，有兼取数义者，有直释名辞者。其兼取数义者，命名之意广有所取也；其直释名辞者，命名之意专在大象也。易者象也，象也者像也，此大象所以尤为一卦之要也。小象之传，辞则简矣，而义至精。或推言爻之德位，而本之于时；或旁及爻之与应，而参之以比；或广其言外之意，而言中之指愈明；或略其言中之词，而所言之理愈备。后之贤者，重言累释而不能尽，圣人辄以单辞括之。此皆经、传之相为发明者，学者当作一意求之，则其文宜相附近，此今日仍王氏旧本之意也。</p><p>伏羲之画，无文而无所不包，文王命之以名，则既偏于一矣。然其审于象也精，而天道民故备焉。此所以为杂而不越，因忧患而有作者也。其辞也，所以发名之意也。如是以开物成务，其亦足矣。其又析为六爻之辞，何也？曰：卦者，原始终以为质，错上下以取象者也。然既有始终矣，则孰为始，孰为终？不可不极其变也。既有上下矣，则孰为上？孰为下？不可不辨其物也。有始终上下，则有消息当否矣，而孰为息？孰为消？孰为当？孰为否？不可不研其几而撰其德也。以泰、否两卦论之，其名卦系辞取于交不交及往来之义矣。然有交不交，则上下判焉；有往有来，则始终分焉。原其始，则自「否」而泰，自「泰」而「否」者也。拔茅而来所以吉，拔茅而去所以亨也。要其终，则「泰」而复否，「否」而复「泰」者也。「城复于隍」，所以吝；「休否倾否」，所以吉也。交而泰，其「泰」在上，故六五有「归妹」之德，而后九二得尽中行之义矣。不交而否，其「否」在下，故六二守「否亨」之节，而九五当存其亡之心矣。「卦包乎爻而举其纲，爻析乎卦而穷其分。爻不立，无以发卦之缊，而冒天下之道。是故卦爻者，相为表里，相为经纬者也。」此文、周之书所为二而一者也。</p><p>名义有相似而累见者，如屯、蹇、困相似也，比、同人、随相似也，颐、井、鼎相似也，晋、升、渐相似也。若此之类，其卦名相似，其彖意爻义亦每重见叠出者，何也？曰：此圣人忧患之心所以为至也。盖理有切于民生日用者，一则烦辞屡申，欲其不忘也；一则辨时析义，欲其不差也。人生于忧患，则屯、蹇、困之义最切矣。非斯人之徒与而谁与？则「比」、同人、随之义最切矣。物不可不养，而养必以正，则「颐」、井、「鼎」之义最切矣。人莫不好进，而进必以正，则「晋」、升、「渐」之义最切矣。广设其名，丁宁其意，凡使之知惧而勿忘焉已矣。而且屯宜动也，「蹇」、困宜止也，相似而不同也。「比」者以分相属也，「同人」者，以情相亲也，「随」者以德相下也，相似而不同也。「颐」者，自养而兼养人之义也，「井」所以养民也，「鼎」所以养贤也，相似而不同也。「晋」者，既进而盛也，「升」者，方进而通也；「渐」者，自方进至既进，缓而有序也，相似而不同也。时义之精也，在毫厘之间，不辨析焉，则用之或差，是故不可以不详也。至于复、临、泰、壮、夬，同为阳长之卦，姤、遁、否、剥，同为阴长之卦，然其微著先后之间，气候不同，而义理亦变。惟圣人为能辨别其当时之几，而审度乎处之之分，莫不于其名卦系辞而见之矣。</p><p>六十四卦皆时也，惟八纯卦不可以时言。非无时也，根于天地之理，人心之德。其为时也，述天理而时措，不可以在外之所遇者言也。乾者，健德也。坤者，顺德也。震者，动德也。艮者，止德也。巽者，入德也。兑者，说德也；离者，明德也。惟坎曰「陷」曰「险」，不可以心德言，故于重卦之名，加一「习」字，与七卦之例别。盖人心惟危，故其心德必有所陷，陷则险矣，于是乎不可听其心之陷溺，而必更习于险以出乎险。孟子所谓「困心衡虑，动心忍性」，皆其事也。如是则亦为人心之德，与七卦等矣。此八卦者，与时偕行，岂非时乎？然主于所施，不主于所遇。是故震与履皆论戒惧之道而不同，震者，心之德也；履者，时之宜也。离与丰皆论昏明之效而不同：离者，心之德也；丰者，时之宜也。艮与咸皆论动静之学而不同：艮者，心之德也；咸者，时之宜也。坎与屯、需、蹇、困皆论处险之义而亦不同，习坎者，心之德也；屯、需、蹇、困，时之宜也。处时之道，不外乎人心之德，此八卦所以经纬乎六十四卦之中，而义所以独为大也。释经者曰：「健莫如天，顺莫如地，动莫如雷，入莫如风，明莫如火，止莫如山，说莫如泽。」是皆然矣。曰险莫如水，则有未尽当曰行险莫如水，斯为水之德尔。由此言之，卦名不加以「习」字，得乎？</p><p>圣人系彖之时，虽通观其卦象、卦德以定名辞之义，然于爻位尤致详焉。盖有因爻位以名卦者，师、比、小畜、履、同人、大有、谦、豫、剥、复、夬、姤之类是也。有名虽别取，而爻位之义发于辞者，屯蒙之「建侯求我」指初二，讼、蹇、萃、巽之「大人」指九五之类是也。是二者，皆谓论卦之主爻，但就文王之名辞观之，有包涵其意而未明者矣。至六爻之系，则辞有吉凶，义有轻重，而名辞之意，因以可见。如师则正九二之为长子，而卦之所以为师者，此矣。比则正九五之为王，而卦之所以为比者，此矣。谦之九三曰「劳谦」，而卦之所以为谦者，此矣。豫之九四曰「由豫」，而卦之所以为「豫」者，此矣。剥之上九曰「硕果」，而卦之所以为剥者，此矣。复之初九曰「不远复」，而卦之所以为「复」者，此矣。又如屯之初曰「利建侯」，而辞所谓「建侯」者，此矣。蒙之五曰「童蒙」，而辞所谓「求我」者，此矣。讼之五曰「讼元吉」，蹇之五曰「大蹇朋来」，萃之五曰「萃有位」，巽之五曰「贞吉悔亡，无不利」，而辞所谓「大人」者，此矣。盖爻之意，虽根于卦而后可明，而卦之意，亦参于爻而后可知。卦爻相求，则所谓主爻者得矣。主爻者得，则其余爻之或吉或凶，因是可推。何则？凡卦义善者，爻能合德则吉，反之则凶也。卦义不善者，爻能反之则吉，合德则凶也。故师、比、谦、豫之类，主爻之吉者也，以其德与时适也。若其当与时反者，则为主者反不得吉。如讼之上九，则终讼者也；履之六三，则咥人者也；明夷上六，则明所以夷也；归妹上六，则妹所以归也。主爻吉，则余爻之吉者，必其德与主爻类者也。非然，则其比应也。而反是者，则凶。主爻凶，则余爻之凶者，必其德与主爻类者也。非然，则其比应也。而反是者，则吉。又主爻不拘于一，如蒙之九二，固主爻矣，六五以「童蒙」应之，则亦主爻也。师之九二，固主爻矣，六五使长子帅师，则亦主爻也。履之六三，固主爻矣，九四有「虎尾」之象，则亦主爻也。泰之九二，固主爻矣，六五为下交之主，则亦主爻也。又如临之初、二，观之五、上，坎、离之二、五，萃、升之四、五，则皆自卦义而定，不妨两为卦主也。又如震有两主，而其重在初。艮有两主，而其重在上。既济二、五得中，而其重在二。未济二、五得中，而其重在五。此则因卦义而变者。履之三、四象「虎尾」，而其吉在四。颐之初、上象「颐」，而其凶在初。大过三、四象「栋」，而其吉在四。小过初、上象「鸟」，而其尤凶在初。此则又因物象而变者。若此之类，推说难尽，姑举其槩，各随卦义爻才而观之可也。凡卦有无主者，则以其义甚大，而爻德不足以配。如「同人于野」之义至大，六二之吝，固不足以当之矣。惟上九居卦外，有「野」之象，而其德非中正，故仅止于「郊」而已。恒久之义至大，六五之「贞」，固不足以当之矣。惟九二刚中，有久中之德，然位失其正，故止于悔亡而已。是二卦者，无主爻也。盖撰德于卦，则指爻以为主者，卦象之正也。系辞其爻，因卦义之大，而必审论其才德者，爻义之精也。艮以人身取象，则当以六四背位为主。然止者刚德，而四柔也，故以上之止体为主，四止于无咎，而上吉也。中孚以中虚取象，则当以三四为主。然孚者实德、中德，三四阴而不中，故以二五之刚中为主，六四虽有几望之吉，而亦不得为主也。然乾坤之义，大之至矣，而其所以有主者，则以乾五刚健中正，备天之德也；坤二柔顺中正，备地之德也。故彖传所谓「乘龙御天」，「首出咸宁」者，皆以九五之德位当之也。文言所谓动刚德方者，皆以六二之德当之也。自乾坤发此例，而六十四卦因之，其彖传有赞爻德以赞卦者，皆此例也。</p><p>所谓占辞者，元亨利贞也，吉凶悔吝无咎也，其目之大者也。考之于经，则爻无元亨，止于「元吉」、「大吉」而已，或止曰亨而已。卦无吝而悔，亦仅见于革彖而已。圣人于此，亦有意否乎？曰：元亨利贞者，天道之常，而贯乎人事者也。吉凶悔吝者，人事之致，而通乎天道者也。卦本乎天道，而元亨者，天道之大者也，故爻不得而用之也。爻主乎人事，而悔吝者，人事之细者也，故卦不得而及之也。且「元亨」之为大也，不独爻无用焉，而见于卦者亦少。自乾坤之外，惟屯、随、临、无妄、革五卦，备「元亨利贞」之辞。盖屯与革，则天时之大者；随人与临人，则人事之大者。无妄，则天人之德之至者也。此外而曰「元亨」者，亦惟大有、蛊、升、鼎而已。蛊坏之极而更新之，其义与屯、革相亚，此所以曰「元亨」也。大有、升、鼎三卦，则皆以贤人取义。盖大有者，所有者大，贤人之众多也。鼎以养贤，贤人之得养也。升以进贤，贤人之得用也。易之义，莫美于用贤者，故大有与鼎，皆直曰「元亨」，而无余辞。升虽有余辞，皆以足「元亨」之义，而无他戒，为诸卦不能及者，意岂不深哉！彖辞言「元亨」，无言「大亨」者，而夫子以「大亨」释之，则「大」与「元」本一义也。然爻辞或言「元吉」，或言「大吉」，则亦不能无少差别。考之坤五、讼五、履上、泰五、复初、大畜四、离二、损五、益初、益五、井上、涣四，皆言「元吉」。惟家人四、萃四、升初、鼎上，言「大吉」。盖坤五以中顺之德配乾，离二亦以中顺而合坤德，故坤曰「牝马」，配乾之义也；离曰「牝牛」，肖坤之义也。其辞皆曰「黄」，以此也。德至中和而极，故占皆「元吉」。履上则德之成也，复初则德之本也，其占亦「元吉」。此四爻皆以其德之纯言也。余则凡言「元吉」者，多指吉之在天下者也。凡言「大吉」者，多指吉之在一人者也。故均之益也，家人四富其家者也；益五富天下者也。均之聚也，萃四聚其下而犹恐有树私之嫌，涣四「涣其群」则已极乎大公之善也。均之进也，益初之义，在忘身以酬上；升初之义，在见允而得升也。均之养也，井之义为养民，则在上而养道成者，是民得养也。鼎之义为养贤，则至上而养道成者，是己得养也。至于讼五、畜四，则有无讼刑措之风焉；泰五、损五，则有虚中受下之美焉。是皆非一人之吉，而天下之吉，此所以不特曰「大」，而曰「元」也。彖传有喜「有庆」之义亦然。彖爻辞有言「利」者，有言「用」者，有言「不利」者，有言「勿用」者，意相近而辞不同。盖占者与卦爻有相为宾主之例。言利不利者，以占者当卦爻，谓如此之德，如此之时位，则其利不利如此也。言用不用者，谓卦爻之德之时如此，占者可用以如此，不可用以如此也。细观之，其义亦须有别。凡言「利」者，皆其事后之利。如讼非得大人不决；蹇非得大人不济；需「不犯难」，同人能得众心，有可以涉川之理。又需者，将以进也；同人者，将以济也。故皆言「利」，事后之辞也。凡言「用」者，则即今而可用。如升则遇时之卦，见大人而无忧；谦谦则德之至，「涉大川」而必济。故皆言「用」，当事之辞也。凡言「不利」者，事无可为之称。如剥之「小人长」，则其时之「不利攸往」也；无妄之「匪正有眚」，则其德之「不利攸往」也。故言「不利」，盖终无可往之理也。凡言「勿用」者，暂且勿用之意。如屯虽动乎险，然犹未可轻有所往；遁虽其势当去，然亦未可轻有所往。故言「勿用」，盖恐其疑于可往，而戒以未可往也。然则「利」之词缓于「用」，「不利」之词又急于「勿用」。通事后而论之，则利者犹在后也，故缓；不利者，终无可为也，故急。即当事而论之，则用者即今可用也，故急。「勿用」者，惟此时勿用而已，故缓。若夫虚言「无不利」、「无攸利」者，亦包当事事后之辞也。虚言「勿用」者，亦是且就其时断之之辞也。颐之三，既曰「勿用」，又曰「无攸利」，则其辞弥甚矣。「利用礿」，利用亨祀，祭祀。及王用亨于西山、岐山，「王用亨于帝」之义，亦然。爻辞无「元亨」，而曰「利贞」者亦少。盖变「元亨」曰「元吉」、「大吉」，变「利贞」曰「贞吉」。所以然者，卦之义全爻则偏指一事而言，故变其文以别之也。其曰「利永贞」者，以永为贞也。「利居贞」者，以居为贞也。「利艰贞」者，以艰为贞也。「利于不息之贞」者，以不息为贞也。「利幽人、武人之贞」者，以幽人、武人为贞也。此又本于坤、明夷彖辞之例，然皆偏指一事而言者也。凡言「贞吉」于辞之后者，即其辞所言之义，而贞固守之则吉也，「需于酒食」、「鸣谦，介于石」之类是也。言「贞吉」于辞之前者，爻有贞吉之义，而辞又有他戒也，咸四、壮四、升五、巽五、未济四五是也。「悔亡」、「无咎」之义亦然。惟壮二直曰「贞吉」，恒二直曰「悔亡」，解初直曰「无咎」，前后更无他辞，则以爻义已足示人，观象之例也。凡言「悔亡」者，有悔而可亡也。「无悔」者，无可悔也。然则「无悔」之义，进于「悔亡」，故咸四言「悔亡」，至五则言「无悔」；大壮四言「悔亡」，至五则言「无悔」；涣二言「悔亡」，至三则言「无悔」；未济四言「悔亡」，至五则言「无悔」。以其辞义先后考之，无悔进于悔亡可知矣。虽以复初之吉，然无祗于悔，与敦复无悔，亦须有先后也。凡易中言「悔亡」、「无悔」者，以此别之。</p><p>先儒说「贞凶」，有云「虽贞亦凶」者，有言「贞乎此则凶」者，有言「决定是凶」者，是有三例也。说「无咎」，既为补过之义，又云「自取凶害，无所归咎」，是有两例也。夫苟二三其例，则是适以眩夫占者，而又何以断天下之疑乎？故夫「贞」者，正也，固也。凡言「贞吉」者，兼正固之义，固由正生也。凡言「贞凶」、「贞吝」、「贞厉」者，主乎固之义，盖自以为正而固守之也。其设戒亦不纯蒙上句，盖有与上句相反为义者，如泰道之终，「城复于隍」矣，斯时也，「勿用师，自邑告命」则可矣。如固守其常而力争之，则「吝」也。晋道之极，「晋其角」矣，斯时也，惟自治其私，则虽危而吉，无咎矣。如固守其常，知进而不知退，则「吝」也。此皆不蒙上句而相反为义者，如「弟子舆尸，贞凶」，「晋如鼫鼠，贞厉，丧其资斧，贞凶」，则蒙上句直说，谓固常如此而不知反，则危且凶也。二者文意不同，然要为不可固守之占，则无两例明矣。传言「无咎者，善补过也」，则「无咎」非凶辞可知。但以大过之上、节之三，遂谓有变例焉。然过上际时穷而有处之之义，节三失时义而有改悔之机，是皆可以补过之例求之，不必变也。盖过涉灭顶，时穷而凶矣。然以柔为说主，不与时争，则「无咎」之道也。不言其所以无咎者，解初六之例也。「不节若」，宜得「凶」矣。然因不节而遂「嗟若」，亦「无咎」之道也，临六三之例也。况节三象传与同人初爻同，则「无咎」之义亦应同。虽解三「又谁咎也」，为非善词，然此两爻有「无咎」之文，则象传为直解「无咎」之义，言人安得而咎我也。解三爻无「无咎」之文，而曰「贞吝」，则象传为解「贞吝」之义，言我安得而咎人也。其辞固不相病也。惟其例之一，是以辞之指有难明者，皆以其占戒读之而可知。故曰：「定之以吉凶，所以断也。」</p><p>王仲淹曰：「趋时有六动焉，吉凶悔吝，所以不同。」其说善矣。然趋时之义，不可不辨也。近代说易，所谓时者，皆似有一时于此，而众人趋之尔。故其象君臣者，皆若同朝；象上下者，皆若同事。其为时也，既局于一而不通；其趋时也，又以互相牵合而说义多不贯，此则讲解之大患也。夫时也者，六位莫不有焉，各立其位，以指其时，非必如并生一世，并营一事者也。如言屯也，蹇也，莫不有屯焉，莫不有蹇焉，不必皆言济时之艰难，平时之险阻也。「大有」也，「豫」也，莫不有所有焉，莫不有所「豫」焉，不必皆言际明盛之朝，值和乐之世也。如此，则何至局于一而不通乎？且莫不有「屯」矣，则初有初之「屯」，五有五之「屯」，非五因初而「屯膏」也。莫不有「豫」矣，则四有四之「豫」，五有五之「豫」，非五因四而「贞疾」也。如此，则何至互相牵合而说不贯乎？盖必其所谓「时」者，广设而周于事，所谓「动而趋时」者，随所处而尽其理，然后有以得圣人贞一群动之心，而于辞也几矣。是故一世之治乱穷通，时也；一身之行止动静，亦时也。因其人，因其事，各有时焉，而各趋之云尔。不然，则何以曰「冒天下之道，而百姓与能」乎？</p><p>考象传凡言「位当」、「不当」者，独三、四、五三爻尔，初、二皆无之。盖所谓「位」者，虽以爻位言，然实借以明分位之义。初居卦下，上处卦外，无位者也。二虽有位，而未高者也。惟五居尊，而三、四皆当高位，故言「位当」、「不当」者，独此三爻详焉。凡言「位当」、「位正当」者，皆谓「德」与「位称」也。不然，则谓时位有所适当，而必善所以处之也。凡言「位不当」、「未当」者，皆谓德不称「位」也。不然，则谓时位有所未当，而必善所以处之也。大传曰：「列贵贱者存乎位。」则知爻位有六，而贵者惟此三爻矣。以象传之言「位当」、「位不当」者，施于此三爻，而不及其他，故知借爻位以明分位之义也。或曰：二虽未高，然亦有位焉，何以不言也？曰：据大传「其柔危，其刚胜邪？」柔之为道，不利远者，则三、五宜刚者也，四宜柔者也，二反宜刚者也。三、四、五以当为善，不当为不善，二则反以不当为善，故当不当之义，不得而施于此爻也。然其于三也，有言不当者矣，未有言当者也。于四也，有言当者矣，未有言正当者也。惟五言「正当」，其言不当者，独「大壮」五而已，而又反以不当为善。盖三，危位也，以柔居之固不当，以刚居之亦未必当也，此其所以多凶也。四近位也，以刚居之固不当，以柔居之亦仅止于「当」而已，此其所以「多惧」也。五尊位也，以刚居之为正当，以柔居之有柔之善焉，虽不当犹当也，此其所以「多功」也。</p><p>何以谓之德也？有根于卦者焉，「健顺」、「动止」、「明说」之类是也；有生于爻者焉，「刚柔」、「中正」之类是也。德无常善，适时为善。故「健顺」、「动止」「明说」之德，失其节则悖矣；刚柔之道，逆其施则拂矣。屯，宜用动者也；蹇，宜用止者也；丰，宜用明者也；困，宜用说者也；需，宜用刚者也；讼，宜用柔者也；贲，宜用刚者也；噬嗑，宜用柔者也；家人，宜用刚者也；旅，宜用柔者也。推此类之，则所谓德之善者可见矣。惟中也，正也，则无不宜也，而中为尤善，何也？易之义莫重于贞，然亦有「贞凶」者矣，有「贞吝」、「贞厉」者矣。其事未必不是也，而逆其时而不知变，且以为正而固守焉，则凶危之道也。中则义之精而用之妙，凡所谓健顺、动止、明说、刚柔之施，于是取裁焉。先儒所谓中则无不正者，此也。或曰：「易之卦爻，于贞盖谆谆焉，其于中行，仅数四见而已，何也？」曰：「正理可识，而中体难明，非深于道者不能知，是故难以察察言也。存其义而没其名，则圣教之精也。自乾、坤二卦，固皆利于贞矣。然所谓二用者，则中之极而贞之源也。其余卦之诸爻，居得其正者多矣，而亦鲜以正许之者。惟二与五得其正者，固曰以中正也。或不得其正者，亦曰中以行正也。是则中道之大，而易教之至也。」「然则存其义而没其名者，何也？」曰：「六十四卦三百八十四爻，所系皆中也。」然必曰如是则得其正，则人皆知道义之是守矣。倘必曰如是乃得其中，则有误于依违两可、混同无辨者，而不自知其非也。故舜之智，必问察乎善而后执其中；颜子之贤，择乎中庸而必得其善。正非中，则正之实未至；中非正，则中之名亦易差。圣人所以尊中之道而略其名，精求乎正之实而必广其教者，此也。</p><p>自王辅嗣说易，多取应爻为义，历代因之。考之夫子彖、象传，言应者盖有之，然亦观爻之一义尔。若逐爻必以应言，恐非周公之意，亦非孔子所以释经之旨也。以经传之例观之，上下两体，阴阳相求，固其正矣。然彖传有以众爻应一爻者，亦有以一爻应众爻者，乃不拘于两体二爻之对比，小畜、同人、大有、豫之类，皆是也。有时义所宜，以阴应阴而吉，以阳应阳而吉者，又不拘于阴阳之偶，晋、小过之「王母祖妣」，睽、丰之「元夫夷主」之类皆是也。有以承乘之爻为重者，则虽有应爻而不取。如观之「观光」，蹇之「来硕」，姤之「包鱼」，鼎之「金铉」，而随则有「失丈夫」之失，观则有「𬮭观」之丑，姤则有「无鱼之凶」，此类皆是也。其余但就其爻之时位、才德起义，而不系于应者，不可胜数，而欲一一以应义傅会之，则凿矣。况爻所谓应者，必隔二位而相应，例也，不隔则非应矣。今有相应而为某爻间隔之说，又有某爻起而争应之说，岂非凿之又凿者乎？说经者因此而不通，所谓至今为梗者矣。经传又无此意，亦奚重而不更也。凡应，惟二五之应最吉，盖皆有中德，而又各居当时之位也。其次则初四间有取焉。三上取应义绝少，其善者又加少也。易之道，阴暗求于阳明，不以阳求阴也；上位求于下位，不以下求上也。故凡六五、九二之有取于应义，则无不吉者，为以阴求阳，德上而下交，则在上者有虚中之美，居下者有自重之实，「蒙」、「师」、「泰」、「大有」之类是也。如取应义者，在于九五、六二，则时义所当，亦有相助之善。然求阳者在于下位，则往往有戒辞焉，屯「比」、「同人」、「萃」之类是也。初与四亦然。如六四、初九取应义，是四求初也，则吉，屯「贲」、「颐」、「损」是也。如九四、初六取应义，是初求四也，则凶，「大过」、「解」、「姤」、「鼎」是也。然吉者在四，而在初者不可变，上虽下交，而下不可以失己也。凶者在初，而在四者与之凶。下既援上，则上未免为失人矣。三上或取应义，皆非吉者，若蒙、颐、睽、夬、丰、中孚之类。惟剥之三与阳应，损之三当益上，于时义有取焉，故二爻无凶辞尔。承乘者谓之比，凡比爻，惟上体所取最多。盖四承五，则如人臣之得君；五承上，则如人主之尊贤。主于五，故其近之者，皆多所取也。然四之承五，惟六四、九五当之。五之承上，惟六五、上九当之。非然者，则亦无得君尊贤之义。惟随之五、上稍变斯例，以时义刚来下柔故尔。其余九五比上六者，皆为刚德之累。上六从九五者，则为从贵之宜，非尊贤者比也。下体三爻，所取比义至少。初与二，二与三，间有相从者，随其时义，或吉或否。至三与四，则隔体无相比之情矣。亦有因时变例取者，随三、萃三是也。</p><p>象也者，像也。故或其卦取于物象，而爻当之，则遂以其义之吉凶断，而爻德犹其次也。如屯所以为屯者，以其雷在下而未起也，初为震主当之，故曰「盘桓」。又以其云在上而未下也，五为坎主当之，故曰「屯膏」。需所以为需，以其云上于天也，九五坎主当之，故为「饮食宴乐」也。履之六三，说而承乾，本卦之主，然因彖言「咥人」，而三适当兑口之缺，有受咥之象，故其传曰「位不当也」，言其直口之位为不当也。颐之初九，本有刚德，能自守者也，以其与上共为颐象。而颐之为物，其动在下，故曰「朵颐」而得「凶」也。咸、艮以人身取象，故咸二虽中正，以直腓位而凶；艮四虽不中正，以直背位而无咎。归妹之凶，以女少而自归故也。初九适当娣象，则不嫌于少，且自归矣。六五适当帝女之象，则亦不嫌于自归矣，故皆得吉也。节取泽与水为通塞，九二适在泽中，则塞之至也，故虽有刚德而凶也。凡若此类，以爻德比应求之，多所不通，惟明于象像之理则得之。又有卦虽取其象，而爻义不应者，则有变例。如噬嗑「颐中有物」，则初上两爻象颐噬人者也；九四一爻象物噬于人者也。然既以用狱为卦义，则用刑者有位之事，故又变其所取之象，以从爻位，四反为刑狱之主，初上反为受刑之人也。</p><p>有一卦六爻，专取一事一物为象，而或一爻别取者，则其义因以异矣。如需诸爻皆取沙泥郊穴之象，而五独曰「需于酒食」，则以五为需之主，有需之德，而所需之安也。蛊诸爻皆象父母，而上独曰「不事王侯」，则以上九居卦之上，无复承于父母之象，人未有不事父母者，故曰「不事王侯」也。咸诸爻皆取身象，惟四不取者，四直心位，因之以论心之感应，而所该者广也。大壮诸爻取羊者三，其曰「壮趾」，曰「藩决」，亦羊象也。惟二不取者，有中德而居下体，不任壮者也。蹇诸爻皆取往来为象，惟二五不言者，五尊位，二王臣之位，义不避难，无往来者也。艮诸爻亦取身象，惟上不取者，九三虽亦艮主，而直心位，然止未极也，至上而后止，极则尽止之道者也。若此之类，皆其权于义者精，故其取于象者审也。或曰：四近君之位，蹇不取四为王臣，而取二，何也？曰：四近也，二远也。当蹇之时，为近臣者，与君同心，来连而已。若冒险阻而济艰难，则远臣之事也，故曰「同功而异位」。</p><p>六爻之辞多称卦名以起其端，例也。然有称有不称者，则义亦异矣。如同人，六爻皆当言同人，然惟三四不言者，既有伏莽乘墉之象，则非同人也。豫，六爻皆当言豫，然惟二五不言者，既有介石之操，贞疾之警，则非豫也。随，六爻皆当言「随」，然初、二、五、上不言，而惟三、四言之，则以阳倡阴随理之正也。初、二、五、上以刚随柔，虽合时义，而非随之正。三、四以柔随刚，虽非时义，而得随之正也。蛊之诸爻言「蛊」，而惟上不言，盖蛊者事也，上不事王侯，则无事矣。然事之坏也，自人心始，上之志可则，则其事莫高而莫尚焉。噬嗑诸爻言「噬」，惟初上别取，初上噬于人者也，不可言噬也。离诸爻皆不言「离」，惟二三言「离」，诸爻皆直昏夜及昏明之际，惟二三直日中与日昃也。遁诸爻皆言「遁」，惟二不言，二应五，不可遁者也。明夷诸爻皆言「明夷」，惟上不言，诸爻皆明而「夷」者，上则夷人之明，而非明夷也。夬诸爻惟三五言「夬」，一近阴，一应阴，当夬之任者也。姤诸爻惟上言「姤」，去初最远，言「遇」者，幸其不遇也。归妹惟二上不言「归妹」，一不归，一无所归也。丰惟初五不言「丰」，一则未至日中，一则有以处乎日中也。旅惟五爻不言「旅」，旅之最贵者，则非旅也。涣惟初爻不言「涣」，涣之初则犹未涣也。节惟初二不言「节」。过而后节，节之初则无所事节也。中孚惟五爻言「孚」，德既中正，而又化邦之主也。既、未济两卦惟未济三爻言「未济」，他爻之既、未济，皆时之为也，惟未济之三时可济矣，而不济，则才之为也，故特言未济以别之也。余卦余爻如此类者，皆可以义理推。周易通论卷一。</p>',20)])])}const h=t(n,[["render",r]]);export{f as __pageData,h as default};
